<?php require __DIR__.'/_head.php';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$s=$pdo->prepare('UPDATE orders SET status=? WHERE id=?');$s->execute([$_POST['status']??'pending',(int)$_POST['id']]);flash('অর্ডারের অবস্থা আপডেট হয়েছে।');header('Location: '.url('admin/orders.php'));exit;}
$orders=$pdo->query('SELECT * FROM orders ORDER BY id DESC')->fetchAll();?>
<div class="card"><h2>অর্ডার ম্যানেজমেন্ট</h2><div class="table-wrap"><table><tr><th>অর্ডার</th><th>কাস্টমার</th><th>যোগাযোগ/ঠিকানা</th><th>চার্জ</th><th>স্ট্যাটাস</th><th>আপডেট</th></tr><?php foreach($orders as $o):?><tr><td>#<?=$o['id']?><br><span class="small"><?=e($o['created_at'])?></span><br><a href="order-view.php?id=<?=$o['id']?>">বিস্তারিত</a></td><td><?=e($o['customer_name'])?></td><td><?=e($o['phone'])?><br><?=e($o['address'])?></td><td><?=money($o['delivery_fee'])?></td><td><?=e($o['status'])?></td><td><form method="post" class="form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$o['id']?>"><select name="status"><?php foreach(['pending','confirmed','processing','shipped','delivered','cancelled'] as $st):?><option value="<?=$st?>" <?=$o['status']===$st?'selected':''?>><?=$st?></option><?php endforeach;?></select><button class="btn">আপডেট</button></form></td></tr><?php endforeach;?></table></div></div><?php require __DIR__.'/_foot.php';?>
